window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a1a33c44be9c8b90"]={"versions": [{"id": "FIG-a1a33c44be9c8b90", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm (Instanzebene der AUTOSAR Metamodell-Definition für ECU-Konfigurationsparameter).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifikation der <em>AUTOSAR ECU Configuration</em> (BSW Parameter Definition).</li>\n<li><strong>Funktionaler Zweck:</strong> Veranschaulichung des Konzepts einer Fremdreferenz (<code>ForeignReferenceDef</code> bzw. <code>EcucForeignReferenceDef</code>). Es definiert den formalen Mechanismus, über den BSW-Konfigurationscontainer Parameter auf Entitäten außerhalb des ECU-Configuration-Metamodells referenzieren – namentlich auf Modellelemente der System-Beschreibung (<em>System Template</em> / <em>System Description</em> wie z. B. Kommunikationsmatrizen für CAN/LIN/FlexRay).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>FrameMapping : ParamConfContainerDef</code>:</strong></li>\n<li>Instanz eines BSW-Konfigurationscontainers (Modul-Parameterdefinition, z. B. im Kontext von <code>Com</code>, <code>CanIf</code> oder PDU-Router-Mappings).</li>\n<li><strong><code>SystemFrame : ForeignReferenceDef</code>:</strong></li>\n<li>Instanz einer Fremdreferenz-Definition.</li>\n<li><strong>Attribut:</strong> <code>destinationType = Frame</code> – erzwingt die semantische und syntaktische Typbindung der Zielinstanz im referenzierten Modell.</li>\n<li><strong><code>Communication::Frame</code> (im Paket <code>System template</code>):</strong></li>\n<li>Metaklasse des AUTOSAR System Templates; erbt von <code>Identifiable</code> (besitzt <code>shortName</code>, UUID etc.).</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ frameID: Int [0..1]</code>: Optionale Identifier-Nummer des Frames auf dem physikalischen Bus.</li>\n<li><code>+ frameLength: Int [1..1]</code>: Obligatorische Frame-Länge (Payload-Größe in Bytes).</li>\n<li><code>+ minimumDelayTime: Float [0..1]</code>: Optionaler Mindestsendeabstand (Inter-Frame-Delay) zur Buslast-Begrenzung.</li>\n<li><strong>Beziehungen:</strong></li>\n<li><strong>Komposition (<code>+reference</code>, gefüllte Raute):</strong> <code>FrameMapping</code> besitzt die Definition <code>SystemFrame</code>.</li>\n<li><strong>Gezielte Abhängigkeit / Referenz (gestrichelter Pfeil):</strong> <code>SystemFrame</code> verweist über <code>destinationType</code> restriktiv auf Instanzen von <code>Communication::Frame</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Metamodell-Instanzdiagramm handelt, liegt kein Laufzeit-Sequenzablauf vor. Der methodische Ablauf zur Konfigurations- und Generierungszeit gestaltet sich wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>System Extract Import:</strong> Bereitstellung des System-Templates (ARXML) mit instanziierten <code>Communication::Frame</code>-Elementen.</li>\n<li><strong>Konfigurationsbindungs-Validierung:</strong> Beim Setzen des Referenzwerts in einem ECU-Konfigurations-Container (<code>EcucContainerValue</code>) prüft das Konfigurationstool, ob das Zielobjekt tatsächlich vom Metatyp <code>destinationType</code> (<code>Frame</code>) ist und von <code>Identifiable</code> abgeleitet wurde.</li>\n<li><strong>Generierungs-Phase:</strong> Der BSW-Code-Generator folgt der Fremdreferenz, liest Attribute wie <code>frameLength</code> und <code>frameID</code> direkt aus dem System Template aus und generiert statische C-Initialisierungsstrukturen (z. B. PDU-Deskriptoren, Mailbox-Konfigurationen und Timer-Limits).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Typstrenge & Validierung:</strong> BSW-Konfigurationseditoren und Validierungs-Skripte müssen Fremdreferenzen schema-validieren. Verweise auf abweichende Metaklassen (z. B. <code>Pdu</code> statt <code>Frame</code>) führen zu Konfigurationsfehlern (<code>BSW-Configuration Violation</code>).</li>\n<li><strong>Multiplizitäten / Nullable Handling:</strong> Da <code>frameID</code> und <code>minimumDelayTime</code> die Kardinalität <code>[0..1]</code> besitzen, müssen Generatoren und nachgelagerte Treiber-Stacks Default-Werte vorsehen oder unvollständige Konfigurationen abfangen (z. B. Frames ohne feste ID bei dynamischen Bussen).</li>\n<li><strong>Entkopplung & Invarianten:</strong> Änderungen am System-Template (z. B. Ändern der <code>frameLength</code> in der DBC/ARXML) erfordern eine Re-Validierung aller abhängigen <code>ForeignReference</code>-Pfade. Werden referenzierte Frames gelöscht oder umbenannt, führt dies zu <em>Dangling References</em> im ECU-Extract.</li>\n<li><strong>Code-Artefakte im Target-Code:</strong> Im generierten C-Code (z. B. <code>CanIf_Cfg.h</code> / <code>Com_Cfg.c</code>) existieren keine String-Pfade, sondern aufgelöste skalare Konstanten (z. B. <code>#define CANIF_RX_PDU_LENGTH 8U</code>).</li>\n</ul>"}, {"id": "FIG-ced75311501ac58b", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm (Instanzebene der AUTOSAR Metamodell-Definition für ECU-Konfigurationsparameter).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifikation der <em>AUTOSAR ECU Configuration</em> (BSW Parameter Definition).</li>\n<li><strong>Funktionaler Zweck:</strong> Veranschaulichung des Konzepts einer Fremdreferenz-Parameterdefinition (<code>ForeignReferenceParamDef</code>). Es definiert den formalen Mechanismus, über den BSW-Konfigurationscontainer Parameter auf Entitäten außerhalb des ECU-Configuration-Metamodells referenzieren – namentlich auf Modellelemente der System-Beschreibung (<em>System Template</em> / <em>System Description</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>FrameMapping : ParamConfContainerDef</code>:</strong></li>\n<li>Instanz eines BSW-Konfigurationscontainers (Modul-Parameterdefinition, z. B. im Kontext von <code>Com</code>, <code>CanIf</code> oder PDU-Router-Mappings).</li>\n<li><strong><code>SystemFrame : ForeignReferenceParamDef</code>:</strong></li>\n<li>Instanz einer Fremdreferenz-Parameterdefinition.</li>\n<li><strong>Attribut:</strong> <code>destinationType = Frame</code> – erzwingt die semantische und syntaktische Typbindung der Zielinstanz im referenzierten Modell.</li>\n<li><strong><code>CoreCommunication::Frame</code> (im Paket <code>System template</code>):</strong></li>\n<li>Metaklasse des AUTOSAR System Templates; erbt von <code>FibexElement</code>.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ frameLength: Int</code>: Obligatorische Frame-Länge (Payload-Größe in Bytes).</li>\n<li><strong>Beziehungen:</strong></li>\n<li><strong>Komposition (<code>+reference</code>, gefüllte Raute):</strong> <code>FrameMapping</code> besitzt die Definition <code>SystemFrame</code>.</li>\n<li><strong>Gezielte Abhängigkeit / Referenz (gestrichelter Pfeil):</strong> <code>SystemFrame</code> verweist über <code>destinationType</code> restriktiv auf Instanzen von <code>CoreCommunication::Frame</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Metamodell-Instanzdiagramm handelt, liegt kein Laufzeit-Sequenzablauf vor. Der methodische Ablauf zur Konfigurations- und Generierungszeit gestaltet sich wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>System Extract Import:</strong> Bereitstellung des System-Templates (ARXML) mit instanziierten <code>CoreCommunication::Frame</code>-Elementen.</li>\n<li><strong>Konfigurationsbindungs-Validierung:</strong> Beim Setzen des Referenzwerts in einem ECU-Konfigurations-Container prüft das Konfigurationstool, ob das Zielobjekt tatsächlich vom Metatyp <code>destinationType</code> (<code>Frame</code>) ist und von <code>FibexElement</code> abgeleitet wurde.</li>\n<li><strong>Generierungs-Phase:</strong> Der BSW-Code-Generator folgt der Fremdreferenz, liest Attribute wie <code>frameLength</code> direkt aus dem System Template aus und generiert statische C-Initialisierungsstrukturen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Typstrenge & Validierung:</strong> BSW-Konfigurationseditoren und Validierungs-Skripte müssen Fremdreferenzen schema-validieren. Verweise auf abweichende Metaklassen führen zu Konfigurationsfehlern.</li>\n<li><strong>Multiplizitäten & Integrität:</strong> Die Frame-Länge (<code>frameLength</code>) ist als obligatorisches Attribut modelliert und muss für die referenzierte Instanz stets definiert sein.</li>\n<li><strong>Entkopplung & Invarianten:</strong> Durch die Kapselung über <code>destinationType = Frame</code> bleibt die Parameterdefinition unabhängig von herstellerspezifischen Systembeschreibungserweiterungen, solange das Ziel die Spezifikation von <code>CoreCommunication::Frame</code> bzw. <code>FibexElement</code> erfüllt.</li>\n</ul>"}, {"id": "FIG-b4b41a01ceb43ac8", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Objektdiagramm (Instanzebene der AUTOSAR Metamodell-Definition für ECU-Konfigurationsparameter).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifikation der <em>AUTOSAR ECU Configuration</em> (BSW Parameter Definition).</li>\n<li><strong>Funktionaler Zweck:</strong> Veranschaulichung des Konzepts einer Fremdreferenz-Parameterdefinition (<code>ForeignReferenceParamDef</code>). Es definiert den formalen Mechanismus, über den BSW-Konfigurationscontainer Parameter auf Entitäten außerhalb des ECU-Configuration-Metamodells referenzieren – namentlich auf Modellelemente der System-Beschreibung (<em>System Template</em> / <em>System Description</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>FrameMapping : ParamConfContainerDef</code>:</strong></li>\n<li>Instanz eines BSW-Konfigurationscontainers (Modul-Parameterdefinition, z. B. im Kontext von <code>Com</code>, <code>CanIf</code> oder PDU-Router-Mappings).</li>\n<li><strong><code>SystemFrame : ForeignReferenceParamDef</code>:</strong></li>\n<li>Instanz einer Fremdreferenz-Parameterdefinition.</li>\n<li><strong>Attribut:</strong> <code>destinationType = Frame</code> – erzwingt die semantische und syntaktische Typbindung der Zielinstanz im referenzierten Modell.</li>\n<li><strong><code>CoreCommunication::Frame</code> (im Paket <code>System template</code>):</strong></li>\n<li>Metaklasse des AUTOSAR System Templates; erbt von <code>FibexElement</code>.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ frameLength :Integer</code>: Obligatorische Frame-Länge (Payload-Größe in Bytes als AUTOSAR-Primitivtyp <code>Integer</code>).</li>\n<li><strong>Beziehungen:</strong></li>\n<li><strong>Komposition (<code>+reference</code>, gefüllte Raute):</strong> <code>FrameMapping</code> besitzt die Definition <code>SystemFrame</code>.</li>\n<li><strong>Gezielte Abhängigkeit / Referenz (gestrichelter Pfeil):</strong> <code>SystemFrame</code> verweist über <code>destinationType</code> restriktiv auf Instanzen von <code>CoreCommunication::Frame</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Metamodell-Instanzdiagramm handelt, liegt kein Laufzeit-Sequenzablauf vor. Der methodische Ablauf zur Konfigurations- und Generierungszeit gestaltet sich wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>System Extract Import:</strong> Bereitstellung des System-Templates (ARXML) mit instanziierten <code>CoreCommunication::Frame</code>-Elementen.</li>\n<li><strong>Konfigurationsbindungs-Validierung:</strong> Beim Setzen des Referenzwerts in einem ECU-Konfigurations-Container prüft das Konfigurationstool, ob das Zielobjekt tatsächlich vom Metatyp <code>destinationType</code> (<code>Frame</code>) ist und von <code>FibexElement</code> abgeleitet wurde.</li>\n<li><strong>Generierungs-Phase:</strong> Der BSW-Code-Generator folgt der Fremdreferenz, liest Attribute wie <code>frameLength</code> direkt aus dem System Template aus und generiert statische C-Initialisierungsstrukturen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Typstrenge & Validierung:</strong> BSW-Konfigurationseditoren und Validierungs-Skripte müssen Fremdreferenzen schema-validieren. Verweise auf abweichende Metaklassen führen zu Konfigurationsfehlern.</li>\n<li><strong>Multiplizitäten & Integrität:</strong> Die Frame-Länge (<code>frameLength</code>) ist als obligatorisches Attribut modelliert und muss für die referenzierte Instanz stets definiert sein.</li>\n<li><strong>Entkopplung & Invarianten:</strong> Durch die Kapselung über <code>destinationType = Frame</code> bleibt die Parameterdefinition unabhängig von herstellerspezifischen Systembeschreibungserweiterungen, solange das Ziel die Spezifikation von <code>CoreCommunication::Frame</code> bzw. <code>FibexElement</code> erfüllt.</li>\n</ul>"}], "trans": [{"from": "FIG-a1a33c44be9c8b90", "to": "FIG-ced75311501ac58b", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SystemFrame</code>: Metaklasse von <code>ForeignReferenceDef</code> zu <code>ForeignReferenceParamDef</code> umbenannt.</li>\n<li><code>Communication::Frame</code>: Zielklasse nach Paketverschiebung zu <code>CoreCommunication::Frame</code> geändert; Generalisierung von <code>Identifiable</code> zu <code>FibexElement</code> geändert.</li>\n<li><code>Communication::Frame</code>: Attribute <code>frameID: Int [0..1]</code> und <code>minimumDelayTime: Float [0..1]</code> entfernt; verbleibendes Attribut ist <code>frameLength: Int</code>.</li>\n</ul>"}, {"from": "FIG-ced75311501ac58b", "to": "FIG-b4b41a01ceb43ac8", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>CoreCommunication::Frame</code>: Typ des Attributs <code>frameLength</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n</ul>"}]};
